import re


def title_of(html: str) -> str:
    """Return the text between the first <title> and </title> in html.

    Tag matching is case-insensitive. Returns an empty string when
    no complete <title> element is present. Does not use the network;
    html is already fetched and passed in.
    """
    m = re.search(r"<title\b[^>]*>(.*?)</title\s*>", html, re.IGNORECASE | re.DOTALL)
    return str(m.group(1)) if m else ""


def test_title_simple() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_title_case_insensitive_tags() -> None:
    assert title_of("<TITLE>Mixed Case</Title>") == "Mixed Case"


def test_title_missing_returns_empty() -> None:
    assert title_of("<html><body>no head here</body></html>") == ""


def test_title_unclosed_returns_empty() -> None:
    assert title_of("<title>never closed") == ""


def test_title_empty_string_input() -> None:
    assert title_of("") == ""


def test_title_uses_first_occurrence() -> None:
    assert title_of("<title>First</title><title>Second</title>") == "First"


def test_title_preserves_inner_whitespace() -> None:
    assert title_of("<title>  spaced  out </title>") == "  spaced  out "
